function renderTopProducts(transactions) {
  const productTotals = groupBy(transactions, 'product');
  const entries = Object.entries(productTotals).sort((a, b) => b[1].revenue - a[1].revenue).slice(0, 6);
  const maxRevenue = entries[0]?.[1].revenue || 1;

